// Generated from indicators/*.pine by node scripts/build.mjs. Do not edit.
window.PINE_SOURCES = {
  "high52": "//@version=6\nindicator(title=\"52-Week High\", shorttitle=\"52W High\", overlay=true, max_bars_back=300)\n\n// ─── Inputs ───────────────────────────────────────────────────────────────────\ngrpHigh        = \"52-Week High\"\nlineColorHigh  = input.color(color.new(color.orange, 0), \"Line Color\",         group=grpHigh)\nlineWidth      = input.int(2,      \"Line Width\",    minval=1, maxval=4,         group=grpHigh)\nlineStyle      = input.string(\"Solid\", \"Line Style\", options=[\"Solid\",\"Dashed\",\"Dotted\"], group=grpHigh)\nshowLabel      = input.bool(true,  \"Show Label\",                                group=grpHigh)\nshowDist       = input.bool(true,  \"Show Distance %\",                           group=grpHigh)\nshowPriceLabel = input.bool(true,  \"Show Price on Axis\",                        group=grpHigh)\nalertProxPct   = input.float(2.0,  \"Proximity Alert (%)\", minval=0.0, step=0.1, group=grpHigh)\n\n// ─── Adaptive Lookback ────────────────────────────────────────────────────────\nIDEAL_BARS = 252\nadaptedLen = math.min(bar_index + 1, IDEAL_BARS)\n\n// ─── Logic ────────────────────────────────────────────────────────────────────\nweekHigh52 = ta.highest(high, adaptedLen)\ndistPct    = (close - weekHigh52) / weekHigh52 * 100\nisNearHigh = math.abs(distPct) <= alertProxPct\n\n// ─── Helper ───────────────────────────────────────────────────────────────────\n_lineStyle(s) =>\n    if s == \"Dashed\"\n        line.style_dashed\n    else if s == \"Dotted\"\n        line.style_dotted\n    else\n        line.style_solid\n\n// ─── Price axis label via plot + plotchar trick ───────────────────────────────\n// This is the native way to get a coloured price tag on the right axis\nplot(showPriceLabel ? weekHigh52 : na, \"52W High Level\",\n     color     = lineColorHigh,\n     linewidth = 1,\n     style     = plot.style_linebr,\n     display   = display.price_scale)\n\n// ─── Drawing ──────────────────────────────────────────────────────────────────\nvar line  highLine  = na\nvar label highLabel = na\n\nif barstate.islast\n    line.delete(highLine)\n    label.delete(highLabel)\n\n    startBar = bar_index - adaptedLen + 1\n\n    highLine := line.new(\n         x1     = startBar,\n         y1     = weekHigh52,\n         x2     = bar_index,\n         y2     = weekHigh52,\n         xloc   = xloc.bar_index,\n         extend = extend.right,\n         color  = lineColorHigh,\n         style  = _lineStyle(lineStyle),\n         width  = lineWidth)\n\n    // ── Chart label (left side of line) ──\n    if showLabel\n        distStr  = showDist ? \" (\" + (distPct >= 0 ? \"+\" : \"\") + str.tostring(distPct, \"#.##\") + \"%)\" : \"\"\n        barsNote = adaptedLen < IDEAL_BARS ? \" [\" + str.tostring(adaptedLen) + \"d]\" : \"\"\n        labelTxt = \"52W High: \" + str.tostring(weekHigh52, format.mintick) + distStr + barsNote\n\n        highLabel := label.new(\n             x         = startBar,\n             y         = weekHigh52,\n             text      = labelTxt,\n             xloc      = xloc.bar_index,\n             yloc      = yloc.price,\n             style     = label.style_label_right,\n             color     = color.new(lineColorHigh, 80),\n             textcolor = lineColorHigh,\n             size      = size.small)\n\n// ─── Data Window only ─────────────────────────────────────────────────────────\nplot(weekHigh52, \"52W High\",            display=display.data_window)\nplot(distPct,    \"Dist% from 52W High\", display=display.data_window)\n\n// ─── Alerts ───────────────────────────────────────────────────────────────────\nalertcondition(isNearHigh,                      \"Near 52W High\",  \"Price is near the 52-Week High!\")\nalertcondition(ta.crossover(close, weekHigh52), \"Broke 52W High\", \"Price broke above the 52-Week High!\")\n",
  "mcdx": "// This Pine Script® code is subject to the terms of the Mozilla Public License 2.0\n// © MCDX Smart Money Indicator - Pine Script v6 Recreation\n// Based on the open-source MCDX formula (RSI-based momentum classifier)\n// Credits: Original concept by Mango2Juice / kgiap123 on TradingView\n//\n// HOW TO READ:\n//   🔴 RED   = Banker (Smart Money / Institutional) → BULLISH signal\n//   🟡 YELLOW = Hot Money (Short-term / Fast traders) → NEUTRAL / cautious\n//   🟢 GREEN  = Retailer (Retail traders) → BEARISH signal (avoid going long)\n//\n//   ✅ Best to go LONG when: RED bars dominate (>50%) and GREEN is low\n//   ❌ Avoid LONG when: GREEN bars dominate (retailers stuck / trapped)\n\n//@version=6\nindicator(title=\"MCDX Smart Money\", shorttitle=\"MCDX\", overlay=false, max_bars_back=500)\n\n// ─── INPUTS ───────────────────────────────────────────────────────────────────\n\nvar string GRP1 = \"🔴 Banker (Smart Money) Settings\"\nbankerBase    = input.int(50,  \"Banker RSI Base\",    minval=10, maxval=90, group=GRP1)\nbankerPeriod  = input.int(50,  \"Banker RSI Period\",  minval=5,  maxval=200, group=GRP1)\nbankerSens    = input.float(1.5, \"Banker Sensitivity\", minval=0.1, maxval=10.0, step=0.1, group=GRP1)\n\nvar string GRP2 = \"🟡 Hot Money Settings\"\nhotBase       = input.int(30,  \"Hot Money RSI Base\",   minval=10, maxval=90, group=GRP2)\nhotPeriod     = input.int(40,  \"Hot Money RSI Period\",  minval=5,  maxval=200, group=GRP2)\nhotSens       = input.float(0.7, \"Hot Money Sensitivity\", minval=0.1, maxval=10.0, step=0.1, group=GRP2)\n\nvar string GRP3 = \"📊 Display Settings\"\nshowMA        = input.bool(true,  \"Show Moving Averages\", group=GRP3)\nmaPeriod      = input.int(10,  \"MA Period\", minval=2, maxval=50, group=GRP3)\nshowBg        = input.bool(true,  \"Show Background Signal\", group=GRP3)\nshowLabels    = input.bool(true,  \"Show % Labels\", group=GRP3)\n\n// ─── COLORS ──────────────────────────────────────────────────────────────────\n\nCOLOR_BANKER   = color.new(color.red,    0)\nCOLOR_HOT      = color.new(#D4AC0D,      0)   // gold/yellow\nCOLOR_RETAIL   = color.new(color.green,  0)\nCOLOR_BANKER_MA = color.new(#FF6B6B,    20)\nCOLOR_HOT_MA   = color.new(#F7DC6F,     20)\nCOLOR_RETAIL_MA = color.new(#58D68D,    20)\n\n// ─── MCDX CALCULATION ────────────────────────────────────────────────────────\n// Formula: sensitivity * (RSI(period) - base), clamped between 0 and 20\n// The \"Retailer\" chip is the remainder: 20 - max(banker, hotmoney)\n\nmcdx_calc(sens, period, base) =>\n    r = ta.rsi(close, period)\n    raw = sens * (r - base)\n    math.max(0.0, math.min(20.0, raw))\n\nbankerVal  = mcdx_calc(bankerSens, bankerPeriod, bankerBase)\nhotVal     = mcdx_calc(hotSens,    hotPeriod,    hotBase)\n\n// Retailer = remaining space up to 20 (after banker takes priority)\n// Retailer fills from the bottom (0 to 20), Banker overlays on top\nretailVal  = math.max(0.0, 20.0 - math.max(bankerVal, hotVal))\n\n// ─── MOVING AVERAGES ─────────────────────────────────────────────────────────\n\nbankerMA  = ta.sma(bankerVal, maPeriod)\nhotMA     = ta.sma(hotVal,    maPeriod)\nretailMA  = ta.sma(retailVal, maPeriod)\n\n// ─── PERCENTAGE LABELS ───────────────────────────────────────────────────────\n\ntotal = bankerVal + hotVal + retailVal\nbankerPct  = total > 0 ? (bankerVal  / total) * 100 : 0.0\nhotPct     = total > 0 ? (hotVal     / total) * 100 : 0.0\nretailPct  = total > 0 ? (retailVal  / total) * 100 : 0.0\n\n// ─── BACKGROUND SIGNAL ───────────────────────────────────────────────────────\n\n// Green BG = Banker dominant (bullish)\n// Red BG   = Retailer dominant (bearish/avoid)\nbgColor = bankerVal > hotVal and bankerVal > retailVal ? color.new(color.green, 92) :\n          retailVal > bankerVal and retailVal > hotVal  ? color.new(color.red,   92) :\n          color.new(color.yellow, 95)\n\nbgcolor(showBg ? bgColor : na, title=\"Background Signal\")\n\n// ─── PLOTS ───────────────────────────────────────────────────────────────────\n\n// Base line at 20 (max level reference)\nhline(20, \"Max Level\",  color=color.new(color.gray, 70), linestyle=hline.style_dashed)\nhline(10, \"Mid Level\",  color=color.new(color.gray, 80), linestyle=hline.style_dotted)\nhline(0,  \"Zero Level\", color=color.new(color.gray, 60), linestyle=hline.style_solid)\n\n// Stacked bars: Retailer (bottom/base = full 20), then Hot Money, then Banker on top\nplot(20,        title=\"Retailer Base\",  style=plot.style_columns, color=COLOR_RETAIL,  linewidth=1)\nplot(hotVal > 0 or bankerVal > 0 ? math.max(hotVal, bankerVal) : na,\n                title=\"Hot Money\",      style=plot.style_columns, color=COLOR_HOT,      linewidth=1)\nplot(bankerVal > 0 ? bankerVal : na,\n                title=\"Banker\",         style=plot.style_columns, color=COLOR_BANKER,   linewidth=1)\n\n// Moving Average Lines\nplot(showMA ? bankerMA  : na, title=\"Banker MA\",  color=COLOR_BANKER_MA,  linewidth=2)\nplot(showMA ? hotMA     : na, title=\"Hot MA\",     color=COLOR_HOT_MA,     linewidth=2)\nplot(showMA ? retailMA  : na, title=\"Retail MA\",  color=COLOR_RETAIL_MA,  linewidth=2)\n\n// ─── INFO TABLE ───────────────────────────────────────────────────────────────\n\nif showLabels and barstate.islast\n    var table infoTable = table.new(position.top_right, 2, 4,\n         bgcolor=color.new(color.black, 70),\n         border_color=color.new(color.gray, 50),\n         border_width=1, frame_color=color.new(color.gray, 50), frame_width=1)\n\n    table.cell(infoTable, 0, 0, \"MCDX\",        text_color=color.white,  text_size=size.small, bgcolor=color.new(color.navy, 30))\n    table.cell(infoTable, 1, 0, \"Value / %\",   text_color=color.silver, text_size=size.small, bgcolor=color.new(color.navy, 30))\n\n    table.cell(infoTable, 0, 1, \"🔴 Banker\",   text_color=color.red,    text_size=size.small)\n    table.cell(infoTable, 1, 1, str.tostring(bankerVal, \"#.##\") + \"  (\" + str.tostring(bankerPct, \"#.#\") + \"%)\",\n               text_color=color.red, text_size=size.small)\n\n    table.cell(infoTable, 0, 2, \"🟡 Hot Money\", text_color=#D4AC0D,     text_size=size.small)\n    table.cell(infoTable, 1, 2, str.tostring(hotVal, \"#.##\") + \"  (\" + str.tostring(hotPct, \"#.#\") + \"%)\",\n               text_color=#D4AC0D, text_size=size.small)\n\n    table.cell(infoTable, 0, 3, \"🟢 Retailer\",  text_color=color.green,  text_size=size.small)\n    table.cell(infoTable, 1, 3, str.tostring(retailVal, \"#.##\") + \"  (\" + str.tostring(retailPct, \"#.#\") + \"%)\",\n               text_color=color.green, text_size=size.small)\n\n// ─── ALERTS ──────────────────────────────────────────────────────────────────\n\nalertcondition(ta.crossover(bankerVal, hotVal),   title=\"Banker Crossover Hot Money\",   message=\"MCDX: Banker crossed above Hot Money — Bullish signal 🔴\")\nalertcondition(ta.crossover(bankerVal, retailVal), title=\"Banker Crossover Retail\",     message=\"MCDX: Banker crossed above Retailer — Strong Bullish 🔴🔴\")\nalertcondition(ta.crossunder(bankerVal, hotVal),  title=\"Banker Crossunder Hot Money\",  message=\"MCDX: Banker fell below Hot Money — Caution ⚠️\")\nalertcondition(bankerVal >= 15,                   title=\"Strong Banker Zone (>= 15)\",   message=\"MCDX: Banker in Strong Zone (≥15) — Institutional accumulation 🏦\")\nalertcondition(retailVal >= 18,                   title=\"Retailer Dominant (>= 18)\",    message=\"MCDX: Retailer dominant — Avoid long, possible distribution 🟢\")\n",
  "pink": "//@version=6\nindicator(\"Pink Candle Indicator [v6]\", overlay=true, max_bars_back=500, max_lines_count=10, max_labels_count=200)\n\n// ============================================================\n//  PINK CANDLE INDICATOR — Pine Script v6\n//  Based on: Buy-on-Dip reversal system using candle colour\n//  signals, dynamic pillow support, shark zone (Tory Box),\n//  and selling/buying climax volume detection.\n//\n//  Signal legend:\n//    PINK   — Potential reversal / standby-to-buy zone\n//    WHITE  — Entry confirmation (White Knight)\n//    YELLOW — Standby-to-sell / take-profit zone\n//    BLUE   — Breakout / momentum signal\n//    GREEN  — Trend confirmed uptrend (above pillow)\n//    RED    — Downtrend / avoid buying\n//    SC tag — Selling Climax (heavy panic sell volume)\n//    BC tag — Buying Climax (exhaustion / consider exit)\n// ============================================================\n\n// ─────────────────────────────────────────────\n// GROUP: PILLOW (Dynamic Support Band)\n// ─────────────────────────────────────────────\ngrp_pillow = \"Pillow Support (Dynamic EMA Band)\"\npillow_len    = input.int(21,    \"Pillow EMA Length\",         group=grp_pillow, minval=5, maxval=200)\npillow_mult   = input.float(0.5, \"Band Width Multiplier\",     group=grp_pillow, minval=0.1, maxval=3.0, step=0.1)\nshow_pillow   = input.bool(true, \"Show Pillow Band\",          group=grp_pillow)\n\n// ─────────────────────────────────────────────\n// GROUP: SHARK ZONE (Tory Box — Institutional Resistance)\n// ─────────────────────────────────────────────\ngrp_shark = \"Shark Zone / Tory Box (Institutional Resistance)\"\nshark_len     = input.int(50,    \"Lookback Period (bars)\",    group=grp_shark, minval=10, maxval=300)\nshark_offset  = input.float(0.5, \"Zone Thickness (%)\",       group=grp_shark, minval=0.1, maxval=5.0, step=0.1)\nshow_shark    = input.bool(true, \"Show Shark Zone\",           group=grp_shark)\n\n// ─────────────────────────────────────────────\n// GROUP: VOLUME CLIMAX\n// ─────────────────────────────────────────────\ngrp_vol = \"Volume Climax Settings\"\nvol_len       = input.int(20,   \"Volume MA Length\",           group=grp_vol, minval=5, maxval=100)\nvol_mult_sc   = input.float(2.0,\"Selling Climax Threshold (x avg)\", group=grp_vol, minval=1.0, maxval=10.0, step=0.1)\nvol_mult_bc   = input.float(2.0,\"Buying Climax Threshold (x avg)\",  group=grp_vol, minval=1.0, maxval=10.0, step=0.1)\nshow_climax   = input.bool(true,\"Show Climax Labels\",         group=grp_vol)\n\n// ─────────────────────────────────────────────\n// GROUP: CANDLE SIGNAL SENSITIVITY\n// ─────────────────────────────────────────────\ngrp_sig = \"Candle Signal Sensitivity\"\nrsi_len       = input.int(14,   \"RSI Length\",                 group=grp_sig, minval=2, maxval=50)\nrsi_os        = input.int(35,   \"RSI Oversold Level (Pink)\",  group=grp_sig, minval=10, maxval=50)\nrsi_ob        = input.int(65,   \"RSI Overbought Level (Yellow)\", group=grp_sig, minval=50, maxval=90)\nstoch_len     = input.int(14,   \"Stoch Length\",               group=grp_sig, minval=5, maxval=50)\nstoch_smooth  = input.int(3,    \"Stoch Smooth\",               group=grp_sig, minval=1, maxval=10)\nbody_pct      = input.float(0.4,\"Min Body Size (% of range)\", group=grp_sig, minval=0.1, maxval=0.9, step=0.05)\n\n// ─────────────────────────────────────────────\n// GROUP: DISPLAY\n// ─────────────────────────────────────────────\ngrp_disp = \"Display Options\"\nshow_labels   = input.bool(true, \"Show Signal Labels on Chart\", group=grp_disp)\nshow_bg       = input.bool(true, \"Colour Candle Backgrounds\",   group=grp_disp)\nshow_table    = input.bool(true, \"Show Signal Dashboard Table\",  group=grp_disp)\nlabel_size    = input.string(\"small\", \"Label Size\", options=[\"tiny\",\"small\",\"normal\",\"large\"], group=grp_disp)\n\n// ─────────────────────────────────────────────\n// COLOURS\n// ─────────────────────────────────────────────\ncol_pink   = color.new(color.fuchsia,  10)\ncol_white  = color.new(color.white,    10)\ncol_yellow = color.new(color.yellow,   10)\ncol_blue   = color.new(color.blue,     10)\ncol_green  = color.new(color.lime,     30)\ncol_red    = color.new(color.red,      30)\ncol_shark  = color.new(color.red,      80)\ncol_pillow = color.new(color.aqua,     80)\ncol_sc     = color.new(color.red,      0)\ncol_bc     = color.new(color.orange,   0)\n\n// ─────────────────────────────────────────────\n// CORE CALCULATIONS\n// ─────────────────────────────────────────────\n\n// — Pillow: EMA ± ATR-based band\npillow_mid   = ta.ema(close, pillow_len)\natr_val      = ta.atr(pillow_len)\npillow_upper = pillow_mid + atr_val * pillow_mult\npillow_lower = pillow_mid - atr_val * pillow_mult\n\n// — Shark Zone: based on highest high over lookback\nshark_high   = ta.highest(high, shark_len)\nshark_top    = shark_high\nshark_bot    = shark_high * (1.0 - shark_offset / 100.0)\n\n// — Volume metrics\nvol_ma       = ta.sma(volume, vol_len)\nvol_ratio    = volume / vol_ma\n\n// — RSI\nrsi_val      = ta.rsi(close, rsi_len)\n\n// — Stochastic\nstoch_k      = ta.sma(ta.stoch(close, high, low, stoch_len), stoch_smooth)\n\n// — Candle body size\ncandle_range = high - low\ncandle_body  = math.abs(close - open)\nbody_ratio   = candle_range > 0 ? candle_body / candle_range : 0.0\n\n// — Trend state (price vs pillow)\nabove_pillow = close > pillow_mid\nbelow_pillow = close < pillow_mid\n\n// — Candle direction\nbull_candle  = close >= open\nbear_candle  = close < open\n\n// ─────────────────────────────────────────────\n// SIGNAL LOGIC\n// ─────────────────────────────────────────────\n\n// ── SELLING CLIMAX (SC)\n// Heavy bear candle + volume surge + RSI oversold\nsc_signal = bear_candle\n          and vol_ratio >= vol_mult_sc\n          and rsi_val < rsi_os + 10\n          and body_ratio > body_pct\n\n// ── BUYING CLIMAX (BC)\n// Heavy bull candle + volume surge + RSI overbought\nbc_signal = bull_candle\n          and vol_ratio >= vol_mult_bc\n          and rsi_val > rsi_ob - 10\n          and body_ratio > body_pct\n\n// ── PINK CANDLE — Standby to Buy\n// Conditions: price near or below pillow, RSI oversold territory,\n// stoch oversold, candle showing early reversal wick (lower wick > body),\n// or immediately after a SC signal\nlower_wick   = math.min(open, close) - low\nupper_wick   = high - math.max(open, close)\nreversal_wick = lower_wick > candle_body * 0.8   // hammer-type wick\n\npink_signal  = below_pillow\n             and rsi_val < rsi_os + 5\n             and stoch_k < 25\n             and (reversal_wick or sc_signal[1] or sc_signal)\n             and not bull_candle[1] == false   // don't fire in strong uptrend\n\n// ── WHITE CANDLE — Entry Signal (White Knight)\n// Strong bull candle after pink, price crossing back above pillow lower band,\n// volume confirms, RSI recovering\nwhite_signal = bull_candle\n             and body_ratio > body_pct\n             and (pink_signal[1] or pink_signal[2] or pink_signal[3])\n             and close > pillow_lower\n             and vol_ratio > 0.8\n             and rsi_val > rsi_val[1]\n\n// ── YELLOW CANDLE — Standby to Sell / Take Profit\n// Price near shark zone OR RSI overbought OR stoch overbought,\n// with a candle showing weakness (small body, upper wick dominant)\nnear_shark   = high >= shark_bot * 0.99\noverbought   = rsi_val > rsi_ob or stoch_k > 75\nupper_wick_dom = upper_wick > candle_body * 0.8  // shooting star / doji wick\n\nyellow_signal = (near_shark or overbought)\n              and above_pillow\n              and (upper_wick_dom or not bull_candle)\n              and not bc_signal\n\n// ── BLUE CANDLE — Breakout Signal\n// Strong bull candle breaking above recent resistance / pillow upper,\n// with strong volume, not in shark zone yet\nbreakout     = close > pillow_upper\n             and close > ta.highest(close, 10)[1]\nblue_signal  = breakout\n             and bull_candle\n             and body_ratio > body_pct\n             and vol_ratio > 1.2\n             and not near_shark\n\n// ── TREND COLOUR\n// Green = price above pillow mid → uptrend context\n// Red   = price below pillow mid → downtrend / danger zone\ntrend_green  = above_pillow and not pink_signal and not white_signal and not yellow_signal and not blue_signal\ntrend_red    = below_pillow and not pink_signal and not white_signal\n\n// ─────────────────────────────────────────────\n// CANDLE COLOURING\n// ─────────────────────────────────────────────\ncandle_col = pink_signal   ? col_pink   :\n             white_signal  ? col_white  :\n             yellow_signal ? col_yellow :\n             blue_signal   ? col_blue   :\n             trend_green   ? col_green  :\n             trend_red     ? col_red    :\n             color.new(color.gray, 50)\n\nbarcolor(candle_col)\n\n// ─────────────────────────────────────────────\n// BACKGROUND HIGHLIGHT\n// ─────────────────────────────────────────────\nbg_col = show_bg ?\n         (pink_signal   ? color.new(color.fuchsia, 92) :\n          white_signal  ? color.new(color.white,   92) :\n          yellow_signal ? color.new(color.yellow,  92) :\n          blue_signal   ? color.new(color.blue,    92) :\n          na) : na\n\nbgcolor(bg_col)\n\n// ─────────────────────────────────────────────\n// PILLOW BAND PLOTS\n// ─────────────────────────────────────────────\np_upper = plot(show_pillow ? pillow_upper : na, \"Pillow Upper\", color=color.new(color.aqua, 70), linewidth=1, style=plot.style_line)\np_lower = plot(show_pillow ? pillow_lower : na, \"Pillow Lower\", color=color.new(color.aqua, 70), linewidth=1, style=plot.style_line)\np_mid   = plot(show_pillow ? pillow_mid   : na, \"Pillow Mid\",   color=color.new(color.aqua, 50), linewidth=2, style=plot.style_line)\nfill(p_upper, p_lower, color=col_pillow, title=\"Pillow Fill\")\n\n// ─────────────────────────────────────────────\n// SHARK ZONE (TORY BOX) — drawn as a band\n// ─────────────────────────────────────────────\np_shark_top = plot(show_shark ? shark_top : na, \"Shark Zone Top\", color=color.new(color.red, 60), linewidth=1, style=plot.style_stepline)\np_shark_bot = plot(show_shark ? shark_bot : na, \"Shark Zone Bot\", color=color.new(color.red, 60), linewidth=1, style=plot.style_stepline)\nfill(p_shark_top, p_shark_bot, color=col_shark, title=\"Shark Zone Fill\")\n\n// ─────────────────────────────────────────────\n// SIGNAL LABELS ON CHART\n// ─────────────────────────────────────────────\nlbl_sz = label_size == \"tiny\"   ? size.tiny   :\n         label_size == \"small\"  ? size.small  :\n         label_size == \"normal\" ? size.normal : size.large\n\nif show_labels\n    if pink_signal\n        label.new(bar_index, low - atr_val * 0.6,\n                  \"🌸 PINK\\nStandby Buy\",\n                  style=label.style_label_up,\n                  color=color.new(color.fuchsia, 20),\n                  textcolor=color.white,\n                  size=lbl_sz)\n\n    if white_signal\n        label.new(bar_index, low - atr_val * 0.6,\n                  \"⚪ WHITE\\nEntry!\",\n                  style=label.style_label_up,\n                  color=color.new(color.white, 10),\n                  textcolor=color.black,\n                  size=lbl_sz)\n\n    if yellow_signal\n        label.new(bar_index, high + atr_val * 0.6,\n                  \"🟡 YELLOW\\nStandby Sell\",\n                  style=label.style_label_down,\n                  color=color.new(color.yellow, 20),\n                  textcolor=color.black,\n                  size=lbl_sz)\n\n    if blue_signal\n        label.new(bar_index, low - atr_val * 0.6,\n                  \"🔵 BLUE\\nBreakout\",\n                  style=label.style_label_up,\n                  color=color.new(color.blue, 20),\n                  textcolor=color.white,\n                  size=lbl_sz)\n\n    if show_climax and sc_signal\n        label.new(bar_index, low - atr_val * 1.2,\n                  \"SC\\nSell Climax\",\n                  style=label.style_label_up,\n                  color=color.new(color.red, 10),\n                  textcolor=color.white,\n                  size=size.tiny)\n\n    if show_climax and bc_signal\n        label.new(bar_index, high + atr_val * 1.2,\n                  \"BC\\nBuy Climax\",\n                  style=label.style_label_down,\n                  color=color.new(color.orange, 10),\n                  textcolor=color.black,\n                  size=size.tiny)\n\n// ─────────────────────────────────────────────\n// SIGNAL DASHBOARD TABLE\n// ─────────────────────────────────────────────\nif show_table and barstate.islast\n    var table dash = table.new(position.top_right, 2, 9,\n                                border_width=1,\n                                border_color=color.new(color.gray, 60),\n                                frame_color=color.new(color.gray, 40),\n                                frame_width=1)\n\n    // Header\n    table.cell(dash, 0, 0, \"PINK CANDLE\",      text_color=color.fuchsia,  text_size=size.small, bgcolor=color.new(color.black, 70), text_halign=text.align_center)\n    table.cell(dash, 1, 0, \"Signal Dashboard\", text_color=color.white,    text_size=size.small, bgcolor=color.new(color.black, 70), text_halign=text.align_center)\n\n    // Active signal\n    active_sig  = pink_signal ? \"🌸 PINK — Standby Buy\" :\n                  white_signal ? \"⚪ WHITE — ENTER\" :\n                  yellow_signal ? \"🟡 YELLOW — TP Zone\" :\n                  blue_signal  ? \"🔵 BLUE — Breakout\" :\n                  sc_signal    ? \"💥 SELL CLIMAX\" :\n                  bc_signal    ? \"🔶 BUY CLIMAX\" :\n                  above_pillow ? \"🟢 Uptrend\" : \"🔴 Downtrend\"\n    sig_col     = pink_signal ? color.fuchsia :\n                  white_signal ? color.white :\n                  yellow_signal ? color.yellow :\n                  blue_signal ? color.blue :\n                  sc_signal ? color.red :\n                  bc_signal ? color.orange :\n                  above_pillow ? color.lime : color.red\n    table.cell(dash, 0, 1, \"Active Signal\",   text_color=color.gray,  text_size=size.tiny, bgcolor=color.new(color.black, 80))\n    table.cell(dash, 1, 1, active_sig,        text_color=sig_col,     text_size=size.tiny, bgcolor=color.new(color.black, 80))\n\n    // RSI\n    rsi_col = rsi_val < rsi_os ? color.lime : rsi_val > rsi_ob ? color.red : color.yellow\n    table.cell(dash, 0, 2, \"RSI (\" + str.tostring(rsi_len) + \")\", text_color=color.gray, text_size=size.tiny, bgcolor=color.new(color.black, 80))\n    table.cell(dash, 1, 2, str.tostring(math.round(rsi_val, 1)),   text_color=rsi_col,   text_size=size.tiny, bgcolor=color.new(color.black, 80))\n\n    // Stochastic\n    stoch_col = stoch_k < 20 ? color.lime : stoch_k > 80 ? color.red : color.yellow\n    table.cell(dash, 0, 3, \"Stoch K\",                  text_color=color.gray,  text_size=size.tiny, bgcolor=color.new(color.black, 80))\n    table.cell(dash, 1, 3, str.tostring(math.round(stoch_k, 1)),   text_color=stoch_col, text_size=size.tiny, bgcolor=color.new(color.black, 80))\n\n    // Volume ratio\n    vol_col = vol_ratio >= vol_mult_sc ? color.red : vol_ratio > 1.5 ? color.orange : color.gray\n    table.cell(dash, 0, 4, \"Volume x Avg\",  text_color=color.gray,  text_size=size.tiny, bgcolor=color.new(color.black, 80))\n    table.cell(dash, 1, 4, str.tostring(math.round(vol_ratio, 2)) + \"x\", text_color=vol_col, text_size=size.tiny, bgcolor=color.new(color.black, 80))\n\n    // Pillow\n    pill_col   = close > pillow_mid ? color.lime : color.red\n    pill_state = close > pillow_upper ? \"Above Band ✓\" : close > pillow_mid ? \"Above Mid ↑\" : close > pillow_lower ? \"Below Mid ↓\" : \"Below Band ✗\"\n    table.cell(dash, 0, 5, \"vs Pillow\",    text_color=color.gray,  text_size=size.tiny, bgcolor=color.new(color.black, 80))\n    table.cell(dash, 1, 5, pill_state,     text_color=pill_col,    text_size=size.tiny, bgcolor=color.new(color.black, 80))\n\n    // Shark zone\n    shark_col   = near_shark ? color.red : color.gray\n    shark_state = high >= shark_top ? \"INSIDE ZONE ⚠\" : near_shark ? \"Near Shark Zone\" : \"Below Shark Zone\"\n    table.cell(dash, 0, 6, \"Shark Zone\",   text_color=color.gray,  text_size=size.tiny, bgcolor=color.new(color.black, 80))\n    table.cell(dash, 1, 6, shark_state,    text_color=shark_col,   text_size=size.tiny, bgcolor=color.new(color.black, 80))\n\n    // Trend\n    trend_col   = above_pillow ? color.lime : color.red\n    trend_state = above_pillow ? \"UPTREND ✓\" : \"DOWNTREND — Caution\"\n    table.cell(dash, 0, 7, \"Trend\",        text_color=color.gray,  text_size=size.tiny, bgcolor=color.new(color.black, 80))\n    table.cell(dash, 1, 7, trend_state,    text_color=trend_col,   text_size=size.tiny, bgcolor=color.new(color.black, 80))\n\n    // SOP reminder\n    sop = white_signal ? \"✅ SOP: Enter now\" :\n          pink_signal  ? \"⏳ SOP: Wait for WHITE\" :\n          yellow_signal? \"💰 SOP: Book profits\" :\n          sc_signal    ? \"👀 SOP: Watch for PINK next\" :\n          blue_signal  ? \"🚀 SOP: Hold with volume\" : \"— Monitor —\"\n    table.cell(dash, 0, 8, \"SOP Hint\",     text_color=color.gray,  text_size=size.tiny, bgcolor=color.new(color.black, 80))\n    table.cell(dash, 1, 8, sop,            text_color=color.white, text_size=size.tiny, bgcolor=color.new(color.black, 80))\n\n// ─────────────────────────────────────────────\n// ALERTS\n// ─────────────────────────────────────────────\nalertcondition(pink_signal,   title=\"PINK Candle — Standby Buy\",   message=\"Pink Candle detected on {{ticker}} ({{interval}}). Potential reversal zone. Standby to buy — wait for WHITE candle confirmation.\")\nalertcondition(white_signal,  title=\"WHITE Candle — Enter Now\",    message=\"White Knight candle on {{ticker}} ({{interval}}). ENTRY SIGNAL — buy-on-dip confirmed. Check volume!\")\nalertcondition(yellow_signal, title=\"YELLOW Candle — Standby Sell\",message=\"Yellow Candle on {{ticker}} ({{interval}}). Take profit zone. Consider booking gains.\")\nalertcondition(blue_signal,   title=\"BLUE Candle — Breakout\",      message=\"Blue Breakout candle on {{ticker}} ({{interval}}). Strong momentum with volume. Breakout confirmed.\")\nalertcondition(sc_signal,     title=\"Selling Climax Detected\",     message=\"Selling Climax (SC) on {{ticker}} ({{interval}}). Heavy panic selling. Watch for Pink Candle reversal next.\")\nalertcondition(bc_signal,     title=\"Buying Climax Detected\",      message=\"Buying Climax (BC) on {{ticker}} ({{interval}}). Exhaustion at top. Consider taking profits.\")\n",
  "zigzag": "//@version=6\nindicator(\"ZigZag [ZZ]\", shorttitle=\"ZZ\", overlay=true, max_lines_count=500, max_labels_count=500)\n\n// ============================================================================\n// ZigZag [ZZ] — Swing High/Low Wave Indicator\n// Connects confirmed swing highs/lows with trend-colored lines, with optional\n// price/% labels and a live \"developing leg\" preview toward the current bar.\n// ============================================================================\n\n// ── Inputs ──────────────────────────────────────────────────────────────\ndepth      = input.int(10, \"Depth (Pivot Strength)\", minval=1, tooltip=\"Bars required on each side of a bar to confirm it as a swing point. Higher = fewer, larger swings. Lower = more, smaller swings.\", group=\"ZigZag Settings\")\nsrcMode    = input.string(\"High/Low\", \"Pivot Source\", options=[\"High/Low\", \"Close\"], group=\"ZigZag Settings\")\n\nshowLabels = input.bool(true, \"Show Price Labels\", group=\"Labels\")\nshowPct    = input.bool(true, \"Show % Change\", group=\"Labels\")\nlabelSize  = input.string(size.small, \"Label Size\", options=[size.tiny, size.small, size.normal, size.large], group=\"Labels\")\n\nlineWidth  = input.int(2, \"Line Width\", minval=1, maxval=6, group=\"Style\")\nupColor    = input.color(#089981, \"Up Leg Color\", group=\"Style\")\ndnColor    = input.color(#f23645, \"Down Leg Color\", group=\"Style\")\nshowDev    = input.bool(true, \"Show Live Developing Leg\", group=\"Style\")\nbgShade    = input.bool(false, \"Shade Background by Trend\", group=\"Style\")\n\n// ── Pivot detection ─────────────────────────────────────────────────────\nuseClose = srcMode == \"Close\"\nfloat ph = useClose ? ta.pivothigh(close, depth, depth) : ta.pivothigh(high, depth, depth)\nfloat pl = useClose ? ta.pivotlow(close, depth, depth)  : ta.pivotlow(low, depth, depth)\n\npivotBar = bar_index - depth\n\n// ── State (persists across bars) ────────────────────────────────────────\nvar int   p2Dir   = 0     // 0 = no pivot yet, 1 = last point is a HIGH, -1 = last point is a LOW\nvar int   p1Bar   = na\nvar float p1Price = na\nvar int   p2Bar   = na\nvar float p2Price = na\nvar line  zzLine  = na\nvar label zzLabel = na\nvar line  devLine = na\n\nnewHighConfirmed = false\nnewLowConfirmed  = false\n\n// ── Helpers ──────────────────────────────────────────────────────────────\nbuildLabelText(_price, _prevPrice) =>\n    txt = str.tostring(_price, format.mintick)\n    if showPct and not na(_prevPrice) and _prevPrice != 0\n        pct = (_price - _prevPrice) / _prevPrice * 100\n        txt := txt + \"\\n\" + (pct >= 0 ? \"+\" : \"\") + str.tostring(pct, \"#.##\") + \"%\"\n    txt\n\nmakeLabel(_bar, _price, _isHigh, _prevPrice) =>\n    label lbl = na\n    if showLabels\n        lbl := label.new(_bar, _price, buildLabelText(_price, _prevPrice),\n                          style=_isHigh ? label.style_label_down : label.style_label_up,\n                          color=color.new(color.white, 100),\n                          textcolor=_isHigh ? dnColor : upColor,\n                          size=labelSize)\n    lbl\n\n// ── Process a new pivot HIGH ──────────────────────────────────────────────\nif not na(ph)\n    if p2Dir <= 0\n        // Reversal: previous point becomes fixed (p1); this high starts the new point (p2)\n        if not na(p2Bar)\n            p1Bar   := p2Bar\n            p1Price := p2Price\n            zzLine  := line.new(p1Bar, p1Price, pivotBar, ph, color=upColor, width=lineWidth)\n            zzLabel := makeLabel(pivotBar, ph, true, p1Price)\n        p2Bar   := pivotBar\n        p2Price := ph\n        p2Dir   := 1\n        newHighConfirmed := true\n    else if ph > p2Price\n        // Continuation: extend the current up-leg to the new, higher high\n        p2Bar   := pivotBar\n        p2Price := ph\n        if not na(zzLine)\n            line.set_x2(zzLine, p2Bar)\n            line.set_y2(zzLine, p2Price)\n        if not na(zzLabel)\n            label.set_x(zzLabel, p2Bar)\n            label.set_y(zzLabel, p2Price)\n            label.set_text(zzLabel, buildLabelText(p2Price, p1Price))\n\n// ── Process a new pivot LOW ───────────────────────────────────────────────\nif not na(pl)\n    if p2Dir >= 0\n        // Reversal: previous point becomes fixed (p1); this low starts the new point (p2)\n        if not na(p2Bar)\n            p1Bar   := p2Bar\n            p1Price := p2Price\n            zzLine  := line.new(p1Bar, p1Price, pivotBar, pl, color=dnColor, width=lineWidth)\n            zzLabel := makeLabel(pivotBar, pl, false, p1Price)\n        p2Bar   := pivotBar\n        p2Price := pl\n        p2Dir   := -1\n        newLowConfirmed := true\n    else if pl < p2Price\n        // Continuation: extend the current down-leg to the new, lower low\n        p2Bar   := pivotBar\n        p2Price := pl\n        if not na(zzLine)\n            line.set_x2(zzLine, p2Bar)\n            line.set_y2(zzLine, p2Price)\n        if not na(zzLabel)\n            label.set_x(zzLabel, p2Bar)\n            label.set_y(zzLabel, p2Price)\n            label.set_text(zzLabel, buildLabelText(p2Price, p1Price))\n\n// ── Live developing leg (dotted preview from last confirmed point to now) ──\nif showDev and not na(p2Bar)\n    if na(devLine)\n        devLine := line.new(p2Bar, p2Price, bar_index, close, color=color.gray, style=line.style_dotted, width=1)\n    else\n        line.set_x1(devLine, p2Bar)\n        line.set_y1(devLine, p2Price)\n        line.set_x2(devLine, bar_index)\n        line.set_y2(devLine, close)\n\n// ── Optional trend background shading ──────────────────────────────────────\nbgcolor(bgShade ? (p2Dir == 1 ? color.new(upColor, 92) : p2Dir == -1 ? color.new(dnColor, 92) : na) : na)\n\n// ── Alerts ──────────────────────────────────────────────────────────────\nalertcondition(newHighConfirmed, title=\"ZZ New Swing High\", message=\"ZZ: new confirmed swing HIGH\")\nalertcondition(newLowConfirmed,  title=\"ZZ New Swing Low\",  message=\"ZZ: new confirmed swing LOW\")\n"
};
